            self.openai_wrapper, PRIME_AGENT_WEIGHT, True, True
        )
        self.agents.append(prime_agent)

    def add_agent(self, agent: MicroAgent) -> None:
        """Adds an agent to the list of agents."""
        self.agents.append(agent)



